/// Far longer than anything here should take, so a slow machine doesn't fail a test.
const TIMEOUT: Duration = Duration::from_secs(60);

const ASSETS: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/assets");

// --- The folder and its writes ---

/// A folder of its own for one test, removed when the test ends.
struct TempDir(PathBuf);

impl TempDir {
    fn new(test: &str) -> Self {
        let path = std::env::temp_dir().join(format!("bni-lifecycle-{}-{test}", process::id()));
        let _ = fs::remove_dir_all(&path);
        Self(path)
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}

/// What a test's store does on every write, between staging the new file and publishing it.
#[derive(Clone, Default)]
struct Writes {
    /// Fails each write there, as a full disk would. The last committed save stays as it was.
    fail: Arc<AtomicBool>,
    /// Holds each write there until cleared.
    hold: Arc<AtomicBool>,
    /// How many writes have reached that point.
    attempts: Arc<AtomicUsize>,
    /// Whether a write is held there now.
    held: Arc<AtomicBool>,
}

impl Writes {
    fn store(&self, dir: &Path) -> WorldStore {
        let writes = self.clone();
        WorldStore::open(dir, RulesPolicy::AsSaved)
            .expect("the folder opens")
            .before_publish(move |_| {
                writes.attempts.fetch_add(1, Ordering::SeqCst);
                while writes.hold.load(Ordering::SeqCst) {
                    writes.held.store(true, Ordering::SeqCst);
                    thread::sleep(Duration::from_millis(5));
                }
                writes.held.store(false, Ordering::SeqCst);
                if writes.fail.load(Ordering::SeqCst) {
                    Err(io::Error::other("the disk is full"))
                } else {
                    Ok(())
                }
            })
    }

    fn attempts(&self) -> usize {
        self.attempts.load(Ordering::SeqCst)
    }

    fn fail(&self, fail: bool) {
        self.fail.store(fail, Ordering::SeqCst);
    }
}

/// The time on the wall, as a test sets it, in seconds since the Unix epoch.
#[derive(Clone, Default)]
struct Wall(Arc<AtomicU64>);

impl Wall {
    fn set(&self, seconds: u64) {
        self.0.store(seconds, Ordering::SeqCst);
    }

    fn at(seconds: u64) -> SystemTime {
        UNIX_EPOCH + Duration::from_secs(seconds)
    }
}

// --- The app ---

/// The primary window's stand-in.
#[derive(Resource)]
struct TestWindow(Entity);

/// Where a test's app keeps the player's settings: beside its saves.
fn settings_store(dir: &Path) -> SettingsStore {
    SettingsStore::new(dir.join("settings"))
}

/// A headless app with the session, the settings, the input policy, the sim bridge, the player
/// and the lifecycle, saving Worlds in `dir` and settings in [`settings_store`], with a wall clock
/// and an app clock the test moves. It starts with the settings kept there, as the game does.
fn lifecycle_app(dir: &Path, writes: &Writes, wall: &Wall) -> App {
    let store = settings_store(dir);
    let loaded = store.load();
    let mut app = App::new();
    app.add_plugins((MinimalPlugins, StatesPlugin, InputPlugin))
        // egui itself needs a renderer. Nothing here is drawn, so egui never wants input.
        .init_resource::<EguiWantsInput>()
        .add_plugins((
            SessionPlugin,
            SettingsPlugin,
            InputPolicyPlugin,
            SimBridgePlugin,
            PlayerPlugin,
            LifecyclePlugin,
        ))
        .insert_resource(TimeUpdateStrategy::ManualDuration(Duration::ZERO))
        .insert_resource(Library::new(writes.store(dir), ASSETS))
        .insert_resource(loaded.settings)
        .insert_resource(SettingsStatus::after_loading(loaded.problems))
        .insert_resource(SettingsStorage::new(store));
    let wall = wall.clone();
    app.insert_resource(WallClock::new(move || {
        Wall::at(wall.0.load(Ordering::SeqCst))
    }));
    let window = app
        .world_mut()
        .spawn((Window::default(), CursorOptions::default(), PrimaryWindow))
        .id();
    app.insert_resource(TestWindow(window));
    // Startup.
    app.update();
    app
}

/// Sends `action`, as a menu does, and runs a frame.
fn act(app: &mut App, action: MenuAction) {
    app.world_mut().write_message(action);
    app.update();
}

/// Runs one frame `duration` of real time long, as the app's clock sees it.
fn step(app: &mut App, duration: Duration) {
    app.insert_resource(TimeUpdateStrategy::ManualDuration(duration));
    app.update();
    app.insert_resource(TimeUpdateStrategy::ManualDuration(Duration::ZERO));
}

/// Runs frames until `done` holds, failing the test after [`TIMEOUT`].
fn update_until(app: &mut App, what: &str, mut done: impl FnMut(&mut App) -> bool) {
    let start = Instant::now();
    loop {
        app.update();
        if done(app) {
            return;
        }
        assert!(start.elapsed() < TIMEOUT, "timed out waiting until {what}");
        thread::sleep(Duration::from_millis(5));
    }
}

/// Presses and releases `key_code` over two frames.
fn tap(app: &mut App, key_code: KeyCode) {
    for state in [ButtonState::Pressed, ButtonState::Released] {
        key(app, key_code, state);
        app.update();
    }
}

/// Presses or releases `key_code`, in time for the next frame.
fn key(app: &mut App, key_code: KeyCode, state: ButtonState) {
    let window = app.world().resource::<TestWindow>().0;
    app.world_mut().write_message(KeyboardInput {
        key_code,
        logical_key: Key::Unidentified(NativeKey::Unidentified),
        state,
        text: None,
        repeat: false,
        window,
    });
}

/// Presses the window's close button.
fn close_window(app: &mut App) {
    let window = app.world().resource::<TestWindow>().0;
    app.world_mut()
        .write_message(WindowCloseRequested { window });
    app.update();
}

fn session(app: &App) -> Session {
    *app.world().resource::<State<Session>>().get()
}

fn play(app: &App) -> Option<Play> {
    app.world()
        .get_resource::<State<Play>>()
        .map(|state| *state.get())
}

fn menu(app: &App) -> &MainMenu {
    app.world().resource::<MainMenu>()
}

fn saving(app: &App) -> &Saving {
    app.world().resource::<Saving>()
}

fn autosave(app: &App) -> Autosave {
    *app.world().resource::<Autosave>()
}

fn departure(app: &App) -> Option<&Departure> {
    app.world().resource::<Leaving>().0.as_ref()
}

fn current(app: &App) -> Option<WorldSummary> {
    app.world()
        .get_resource::<CurrentWorld>()
        .map(|current| current.0.clone())
}

fn store(app: &App) -> WorldStore {
    app.world()
        .resource::<Library>()
        .store()
        .expect("the test's store")
        .clone()
}

fn tick(app: &App) -> u64 {
    app.world().resource::<SimReport>().tick
}

/// The player's body and camera rotation, once they are released.
fn player(app: &mut App) -> Option<(Body, Quat)> {
    app.world_mut()
        .query_filtered::<(&Player, &Transform), Without<AwaitingSpawn>>()
        .iter(app.world())
        .next()
        .map(|(player, transform)| (**player, transform.rotation))
}

fn cell_of(feet: Vec3) -> CellPos {
    let cell = feet.floor().as_ivec3();
    CellPos::new(cell.x, cell.y, cell.z)
}

/// Waits for the main menu's job to end.
fn menu_idle(app: &mut App) {
    update_until(app, "the main menu's job ends", |app| {
        menu(app).job.is_none()
    });
}

/// Waits until the World is open, its player released and its save idle.
fn world_ready(app: &mut App) {
    update_until(app, "the World opens and its player is released", |app| {
        session(app) == Session::Open && player(app).is_some()
    });
}

/// Creates a World from the main menu and waits until it can be played.
fn new_game(app: &mut App, name: &str, seed: Option<u64>) -> WorldSummary {
    menu_idle(app);
    act(
        app,
        MenuAction::NewGame {
            name: name.into(),
            seed,
        },
    );
    world_ready(app);
    current(app).expect("a World from the main menu is the current World")
}

/// Loads a World from the main menu and waits until it can be played.
fn load_game(app: &mut App, id: WorldId) {
    menu_idle(app);
    act(app, MenuAction::LoadGame(id));
    world_ready(app);
}

/// Returns to the main menu and waits until it has listed the Worlds.
fn return_to_menu(app: &mut App) {
    act(app, MenuAction::ReturnToMainMenu);
    update_until(app, "the main menu shows", |app| {
        session(app) == Session::Closed && menu(app).job.is_none()
    });
}

/// Pauses on Esc, and waits for the simulation to acknowledge it.
fn pause(app: &mut App) {
    tap(app, KeyCode::Escape);
    update_until(app, "the pause completes", |app| {
        play(app) == Some(Play::Paused)
    });
}

/// Waits until the latest save has ended, and returns how.
fn save_ended(app: &mut App) -> SaveStatus {
    update_until(app, "the save ends", |app| {
        saving(app).in_progress().is_none()
    });
    saving(app).last.clone()
}

/// The names of the listed Worlds, in the list's order.
fn listed_names(app: &App) -> Vec<String> {
    menu(app)
        .worlds
        .iter()
        .map(|row| match &row.world {
            Ok(world) => world.name.clone(),
            Err(why) => format!("unreadable: {why}"),
        })
        .collect()
}

/// A Cell of Granite, placed in the air above the player's feet, where nothing generated is
/// solid. Solids don't move, so it stays there.
fn place_granite_above(app: &mut App) -> CellPos {
    let (body, _) = player(app).expect("the player");
    let feet = cell_of(body.feet);
    let pos = CellPos::new(feet.x, feet.y + 10, feet.z);
    let granite = app
        .world()
        .resource::<Elements>()
        .id_of("Granite")
        .expect("the shipped Elements have Granite");
    app.world()
        .resource::<SimBridge>()
        .send(SimCommand::Edit(Edit::Place {
            pos,
            cell: Cell {
                element: granite,
                mass_grams: 2_700_000,
                temperature_k: 290.0,
            },
        }));
    update_until(app, "the Granite shows up", |app| {
        granite_at(app, pos) == Some(true)
    });
    pos
}

/// Whether the Cell at `pos` holds Granite, once its Chunk is in the world view.
fn granite_at(app: &App, pos: CellPos) -> Option<bool> {
    let granite = app.world().resource::<Elements>().id_of("Granite")?;
    let cell = app.world().resource::<WorldView>().cell(pos)?;
    Some(cell.element == granite)
}

/// Sends `action`, as the Settings page does, and runs a frame.
fn settings_act(app: &mut App, action: SettingsAction) {
    app.world_mut().write_message(action);
    app.update();
}

/// The Settings page's editor, while it is open.
fn settings_page(app: &mut App) -> Option<Mut<'_, blocks_not_included::settings::SettingsEditor>> {
    let page = app.world_mut().resource_mut::<SettingsPage>();
    if page.is_open() {
        Some(page.map_unchanged(|page| page.editor_mut().expect("open")))
    } else {
        None
    }
}

/// Changes the settings as a player does: pauses, opens the Settings page, changes the draft,
/// applies it, goes back to the pause menu with Esc, and resumes with Esc.
fn change_settings(app: &mut App, change: impl FnOnce(&mut Settings)) {
    pause(app);
    settings_act(app, SettingsAction::Open);
    change(&mut settings_page(app).expect("the page opens").draft);
    settings_act(app, SettingsAction::Apply);
    assert_eq!(
        app.world().resource::<SettingsStatus>().applied,
        Some(Ok(())),
        "the settings are kept"
    );
    tap(app, KeyCode::Escape);
    assert!(settings_page(app).is_none(), "Esc goes back");
    assert_eq!(play(app), Some(Play::Paused));
    tap(app, KeyCode::Escape);
    assert_eq!(play(app), Some(Play::Running));
}

/// The keys that systems in `Update` saw pressed.
#[derive(Resource, Default)]
struct SeenKeys(Vec<KeyCode>);

fn record_keys(keys: Res<ButtonInput<KeyCode>>, mut seen: ResMut<SeenKeys>) {
    seen.0.extend(keys.get_just_pressed());
}

/// Resizes the test window, as the window system does.
fn set_window_size(app: &mut App, width: u32, height: u32) {
    let entity = app.world().resource::<TestWindow>().0;
    let mut window = app
        .world_mut()
        .get_mut::<Window>(entity)
        .expect("the window");
    window.resolution.set_physical_resolution(width, height);
}

/// The test window's mode and size in physical pixels.
fn window(app: &App) -> (WindowMode, UVec2) {
    let entity = app.world().resource::<TestWindow>().0;
    let window = app.world().get::<Window>(entity).expect("the window");
    (window.mode, window.resolution.physical_size())
}

// --- Tests ---

#[test]
fn seeds_are_blank_or_whole_numbers_up_to_the_largest_u64() {
    assert_eq!(parse_seed(""), Ok(None));
    assert_eq!(parse_seed("   "), Ok(None));
    assert_eq!(parse_seed("0"), Ok(Some(0)));
    assert_eq!(parse_seed(" 2026 "), Ok(Some(2026)));
    assert_eq!(
        parse_seed("18446744073709551615"),
        Ok(Some(u64::MAX)),
        "u64::MAX = 2⁶⁴ − 1"
    );
    assert_eq!(parse_seed("18446744073709551616"), Err(SeedError::TooLarge));
    for not_a_number in ["-1", "+5", "1.5", "1e3", "0x10", "12 34", "seed"] {
        assert_eq!(
            parse_seed(not_a_number),
            Err(SeedError::NotANumber),
            "{not_a_number}"
        );
    }
}

/// Seam 1: the main menu's actions. No simulation runs at launch. Two Worlds created with the same
/// name and seed are distinct, each saved before its first Tick. An Edit saved in one doesn't
/// show in the other, and each loads as it was left. Closing the window saves the World and quits.
#[test]
fn new_game_and_load_game_open_worlds_that_change_independently() {
    let dir = TempDir::new("menu");
    let (writes, wall) = (Writes::default(), Wall::default());
    let mut app = lifecycle_app(&dir.0, &writes, &wall);

    assert_eq!(session(&app), Session::Closed);
    assert!(app.world().get_resource::<SimBridge>().is_none());
    menu_idle(&mut app);
    assert!(menu(&app).worlds.is_empty());
    assert_eq!(menu(&app).problem, None);

    // The first World: saved as it opens, before its first Tick, with its player on the ground.
    wall.set(1_000);
    let first = new_game(&mut app, "Twins", Some(42));
    assert_eq!((first.name.as_str(), first.seed), ("Twins", 42));
    assert_eq!(first.last_played, Wall::at(1_000));
    let initial = store(&app).load(&first.id).expect("the first save loads");
    let checkpoint = &initial.save.capture.checkpoint;
    assert_eq!(checkpoint.tick_count, 0);
    let (body, rotation) = player(&mut app).expect("the player");
    assert_eq!(cell_of(initial.save.player.body.feet), cell_of(body.feet));
    assert_eq!(checkpoint.focus, cell_of(body.feet));
    // The rotation goes through yaw and pitch on its way to the save and back. In f32, the
    // `acos` in `angle_between` can't tell angles below about 7e-4 rad apart from 0.
    assert!(initial.save.player.rotation().angle_between(rotation) < 1e-3);
    return_to_menu(&mut app);
    assert_eq!(listed_names(&app), ["Twins"]);

    // The second, with the same name and seed: another World.
    wall.set(2_000);
    let second = new_game(&mut app, "Twins", Some(42));
    assert_ne!(second.id, first.id);
    assert_eq!(second.seed, 42);
    let granite = place_granite_above(&mut app);
    pause(&mut app);
    wall.set(3_000);
    act(&mut app, MenuAction::Save);
    assert_eq!(
        saving(&app).in_progress(),
        Some(SaveReason::Manual),
        "the save starts that frame"
    );
    assert!(matches!(
        save_ended(&mut app),
        SaveStatus::Saved {
            reason: SaveReason::Manual,
            ..
        }
    ));
    assert_eq!(
        current(&app).map(|world| world.last_played),
        Some(Wall::at(3_000))
    );
    wall.set(3_500);
    return_to_menu(&mut app);
    assert!(app.world().get_resource::<SimBridge>().is_none());
    assert!(app.world().get_resource::<CurrentWorld>().is_none());
    // The most recently played first.
    let ids: Vec<WorldId> = menu(&app).worlds.iter().map(|row| row.id).collect();
    assert_eq!(ids, [second.id, first.id]);

    // The first World never had the Edit.
    load_game(&mut app, first.id);
    assert_eq!(current(&app).map(|world| world.id), Some(first.id));
    update_until(&mut app, "the Edit's Chunk loads", |app| {
        granite_at(app, granite).is_some()
    });
    assert_eq!(granite_at(&app, granite), Some(false));
    wall.set(4_000);
    return_to_menu(&mut app);
    let ids: Vec<WorldId> = menu(&app).worlds.iter().map(|row| row.id).collect();
    assert_eq!(ids, [first.id, second.id]);

    // The second World kept it.
    load_game(&mut app, second.id);
    update_until(&mut app, "the Edit's Chunk loads", |app| {
        granite_at(app, granite).is_some()
    });
    assert_eq!(granite_at(&app, granite), Some(true));

    // Closing the window saves the World as it stands, then quits.
    let ticks = 2;
    let started = tick(&app);
    update_until(&mut app, "a couple of Ticks run", |app| {
        tick(app) >= started + ticks
    });
    wall.set(5_000);
    close_window(&mut app);
    assert_eq!(app.should_exit(), None, "the World saves first");
    assert_eq!(play(&app), Some(Play::Leaving));
    let frozen_at = {
        update_until(&mut app, "the World freezes", |app| {
            app.world().resource::<SimBridge>().frozen_at().is_some()
        });
        app.world()
            .resource::<SimBridge>()
            .frozen_at()
            .expect("frozen")
    };
    update_until(&mut app, "the game quits", |app| {
        app.should_exit().is_some()
    });
    assert_eq!(app.should_exit(), Some(AppExit::Success));
    let left = store(&app).load(&second.id).expect("the save loads");
    assert_eq!(left.summary.last_played, Wall::at(5_000));
    assert_eq!(left.save.capture.checkpoint.tick_count, frozen_at);
    assert!(frozen_at >= started + ticks);
}

/// Seam 2, with the app's clock stepped by hand: only unpaused play counts towards an autosave,
/// and each save that commits, by the player or by itself, starts the count again.
#[test]
fn autosaves_count_unpaused_play_from_the_last_save() {
    let dir = TempDir::new("autosave");
    let (writes, wall) = (Writes::default(), Wall::default());
    let mut app = lifecycle_app(&dir.0, &writes, &wall);
    let world = new_game(&mut app, "Clockwork", Some(7));
    let interval = autosave(&app).interval;
    assert_eq!(interval, Duration::from_secs(60), "the default: a minute");
    let writes_at_start = writes.attempts();

    step(&mut app, Duration::from_secs(30));
    assert_eq!(autosave(&app).since_save, Duration::from_secs(30));
    assert_eq!(saving(&app).in_progress(), None);

    // Paused, play time stands still.
    pause(&mut app);
    for _ in 0..4 {
        step(&mut app, Duration::from_secs(30));
    }
    assert_eq!(autosave(&app).since_save, Duration::from_secs(30));
    assert_eq!(writes.attempts(), writes_at_start);
    tap(&mut app, KeyCode::Escape);
    assert_eq!(play(&app), Some(Play::Running));

    // 30 s + 30 s = 60 s of play: due.
    wall.set(10_000);
    step(&mut app, Duration::from_secs(30));
    assert_eq!(saving(&app).in_progress(), Some(SaveReason::Autosave));
    assert!(matches!(
        save_ended(&mut app),
        SaveStatus::Saved {
            reason: SaveReason::Autosave,
            ..
        }
    ));
    assert_eq!(writes.attempts(), writes_at_start + 1);
    assert_eq!(autosave(&app).since_save, Duration::ZERO);
    let saved = store(&app).load(&world.id).expect("the autosave loads");
    assert_eq!(saved.summary.last_played, Wall::at(10_000));
    assert_eq!(saved.summary.name, "Clockwork");

    // A save the player asks for starts the count again too.
    step(&mut app, Duration::from_secs(50));
    act(&mut app, MenuAction::Save);
    assert!(matches!(
        save_ended(&mut app),
        SaveStatus::Saved {
            reason: SaveReason::Manual,
            ..
        }
    ));
    assert_eq!(autosave(&app).since_save, Duration::ZERO);
    step(&mut app, Duration::from_secs(50));
    assert_eq!(
        saving(&app).in_progress(),
        None,
        "50 s after the player's save, not 100 s after the autosave"
    );
    step(&mut app, Duration::from_secs(10));
    assert_eq!(saving(&app).in_progress(), Some(SaveReason::Autosave));
    save_ended(&mut app);
    assert_eq!(writes.attempts(), writes_at_start + 3);
}

/// Seam 2: an autosave that fails keeps the last save and the game running, and is tried again
/// only a whole interval later, not on every frame.
#[test]
fn a_failed_autosave_keeps_the_last_save_and_waits_an_interval_to_try_again() {
    let dir = TempDir::new("failed-autosave");
    let (writes, wall) = (Writes::default(), Wall::default());
    let mut app = lifecycle_app(&dir.0, &writes, &wall);
    let world = new_game(&mut app, "Brittle", Some(11));
    let path = store(&app).path_of(&world.id);
    let committed = fs::read(&path).expect("the first save");

    writes.fail(true);
    let attempts = writes.attempts();
    step(&mut app, Duration::from_secs(60));
    let SaveStatus::Failed {
        reason: SaveReason::Autosave,
        message,
        ..
    } = save_ended(&mut app)
    else {
        panic!("the autosave fails");
    };
    assert!(message.contains("the disk is full"), "{message}");
    assert_eq!(writes.attempts(), attempts + 1);
    assert_eq!(fs::read(&path).expect("the save"), committed);
    assert_eq!(play(&app), Some(Play::Running), "play carries on");

    // No retry on the frames after.
    for _ in 0..20 {
        step(&mut app, Duration::from_secs(1));
    }
    assert_eq!(saving(&app).in_progress(), None);
    assert_eq!(writes.attempts(), attempts + 1);

    // The player's own save fails the same way, and doesn't restart the count.
    act(&mut app, MenuAction::Save);
    assert!(matches!(
        save_ended(&mut app),
        SaveStatus::Failed {
            reason: SaveReason::Manual,
            ..
        }
    ));
    assert_eq!(fs::read(&path).expect("the save"), committed);
    assert_eq!(autosave(&app).since_save, Duration::from_secs(20));

    // An interval after the failed one, the autosave is tried again, and commits.
    writes.fail(false);
    step(&mut app, Duration::from_secs(39));
    assert_eq!(saving(&app).in_progress(), None);
    step(&mut app, Duration::from_secs(1));
    assert_eq!(saving(&app).in_progress(), Some(SaveReason::Autosave));
    assert!(matches!(
        save_ended(&mut app),
        SaveStatus::Saved {
            reason: SaveReason::Autosave,
            ..
        }
    ));
    assert_ne!(fs::read(&path).expect("the save"), committed);
    store(&app).load(&world.id).expect("the new save loads");
}

/// Step 20, seam 3: each autosave interval the player can choose in Settings is counted in
/// unpaused play, as step 19's single interval was. The interval kept from the last run applies
/// from the start.
#[test]
fn each_autosave_interval_chosen_in_settings_counts_unpaused_play() {
    let dir = TempDir::new("autosave-intervals");
    let (writes, wall) = (Writes::default(), Wall::default());
    let kept = Settings {
        autosave: AutosaveInterval::ThreeMinutes,
        ..Settings::default()
    };
    settings_store(&dir.0).save(&kept).expect("kept");
    let mut app = lifecycle_app(&dir.0, &writes, &wall);
    assert_eq!(autosave(&app).interval, Duration::from_secs(3 * 60));

    new_game(&mut app, "Metronome", Some(3));
    for interval in AutosaveInterval::ALL {
        change_settings(&mut app, |draft| draft.autosave = interval);
        assert_eq!(autosave(&app).interval, interval.duration());
        // The World has saved, or just opened, and stood paused since.
        assert_eq!(autosave(&app).since_save, Duration::ZERO);
        let attempts = writes.attempts();

        step(&mut app, interval.duration() - Duration::from_secs(1));
        assert_eq!(saving(&app).in_progress(), None, "{interval:?}");
        step(&mut app, Duration::from_secs(1));
        assert_eq!(
            saving(&app).in_progress(),
            Some(SaveReason::Autosave),
            "{interval:?}"
        );
        assert!(matches!(
            save_ended(&mut app),
            SaveStatus::Saved {
                reason: SaveReason::Autosave,
                ..
            }
        ));
        assert_eq!(writes.attempts(), attempts + 1);
        assert_eq!(autosave(&app).since_save, Duration::ZERO);
    }
    assert_eq!(
        settings_store(&dir.0).load().settings.autosave,
        AutosaveInterval::TenMinutes,
        "the last choice is kept"
    );
}

/// Step 20: the Settings page over the pause menu. It opens only while the World is paused, and
/// the World stays paused while it is open. Esc stops listening for a control, then goes back to
/// the pause menu without resuming. The keys pressed to bind controls reach nothing else. What
/// the page applies takes effect at once, and is kept.
#[test]
fn settings_over_the_pause_menu_keep_the_world_paused_and_apply_at_once() {
    let dir = TempDir::new("settings-page");
    let (writes, wall) = (Writes::default(), Wall::default());
    let mut app = lifecycle_app(&dir.0, &writes, &wall);
    app.init_resource::<SeenKeys>()
        .add_systems(Update, record_keys);
    new_game(&mut app, "Dials", Some(5));
    for _ in 0..40 {
        step(&mut app, Duration::from_millis(50));
    }
    assert!(player(&mut app).expect("the player").0.grounded);

    // Not while the World runs.
    settings_act(&mut app, SettingsAction::Open);
    assert!(settings_page(&mut app).is_none());

    pause(&mut app);
    settings_act(&mut app, SettingsAction::Open);
    assert!(settings_page(&mut app).is_some());
    let frozen = tick(&app);

    // Jump goes to J. The press binds it and is used up.
    settings_page(&mut app).expect("open").listen(Action::Jump);
    app.world_mut().resource_mut::<SeenKeys>().0.clear();
    tap(&mut app, KeyCode::KeyJ);
    let editor = settings_page(&mut app).expect("open");
    assert_eq!(
        editor.draft.bindings.inputs(Action::Jump),
        [Input::Key(KeyCode::KeyJ)]
    );
    assert_eq!(*editor.rebinding(), Rebinding::Idle);

    // Esc while listening only stops listening.
    settings_page(&mut app).expect("open").listen(Action::Dig);
    tap(&mut app, KeyCode::Escape);
    let editor = settings_page(&mut app).expect("still open");
    assert_eq!(*editor.rebinding(), Rebinding::Idle);
    assert_eq!(play(&app), Some(Play::Paused));
    assert_eq!(
        app.world().resource::<SeenKeys>().0,
        [],
        "J and Esc reached nothing else"
    );

    // Borderless fullscreen applies to the window at once, and Jump and the sensitivity with it.
    let mut editor = settings_page(&mut app).expect("open");
    editor.draft.display.mode = DisplayMode::BorderlessFullscreen;
    editor.draft.mouse_sensitivity = 2.0;
    settings_act(&mut app, SettingsAction::Apply);
    app.update();
    assert_eq!(
        window(&app).0,
        WindowMode::BorderlessFullscreen(MonitorSelection::Current)
    );
    let applied = app.world().resource::<Settings>().clone();
    assert_eq!(
        applied.bindings.inputs(Action::Jump),
        [Input::Key(KeyCode::KeyJ)]
    );

    // Back to a window, at the size chosen.
    settings_page(&mut app).expect("open").draft.display = blocks_not_included::settings::Display {
        mode: DisplayMode::Windowed,
        window_size: WindowSize::new(1600, 900),
    };
    settings_act(&mut app, SettingsAction::Apply);
    app.update();
    assert_eq!(window(&app), (WindowMode::Windowed, UVec2::new(1600, 900)));
    // Leaving fullscreen, a window manager may restore the size from before after the game asked
    // for its own. The game asks again.
    set_window_size(&mut app, 1280, 720);
    app.update();
    assert_eq!(window(&app).1, UVec2::new(1600, 900));
    // Once the window has settled, the player may resize it.
    step(&mut app, Duration::from_secs(2));
    set_window_size(&mut app, 1000, 700);
    app.update();
    assert_eq!(window(&app).1, UVec2::new(1000, 700));
    let applied = app.world().resource::<Settings>().clone();
    assert_eq!(
        settings_store(&dir.0).load().settings,
        applied,
        "what applies is kept"
    );

    // Esc goes back to the pause menu, and the World stays paused.
    tap(&mut app, KeyCode::Escape);
    assert!(settings_page(&mut app).is_none());
    assert_eq!(play(&app), Some(Play::Paused));
    let started = Instant::now();
    while started.elapsed() < Duration::from_millis(600) {
        app.update();
        thread::sleep(Duration::from_millis(10));
    }
    assert_eq!(tick(&app), frozen, "no Tick ran while Settings was open");
    tap(&mut app, KeyCode::Escape);
    assert_eq!(play(&app), Some(Play::Running));

    // Space no longer jumps; J does.
    key(&mut app, KeyCode::Space, ButtonState::Pressed);
    step(&mut app, Duration::from_millis(50));
    assert!(player(&mut app).expect("the player").0.velocity.y <= 0.0);
    key(&mut app, KeyCode::Space, ButtonState::Released);
    key(&mut app, KeyCode::KeyJ, ButtonState::Pressed);
    step(&mut app, Duration::from_millis(50));
    // It leaves at 8 m/s, less 25 m/s² × 0.05 s of gravity: 6.75 m/s.
    let velocity = player(&mut app).expect("the player").0.velocity.y;
    assert!((velocity - 6.75).abs() < 1e-3, "{velocity}");

    // The mouse turns the view twice as fast as before.
    let yaw = |app: &mut App| player(app).expect("the player").1.to_euler(EulerRot::YXZ).0;
    let before = yaw(&mut app);
    app.world_mut().write_message(MouseMotion {
        delta: Vec2::new(-100.0, 0.0),
    });
    app.update();
    // 100 px × 0.002 rad/px × 2 = 0.4 rad, to the left.
    let turned = (yaw(&mut app) - before).rem_euclid(TAU);
    assert!((turned - 0.4).abs() < 1e-4, "{turned}");
}

/// Seam 3: loads, renames and deletes that fail leave the player at the list, with the World
/// selected and its save as it was. A rename keeps the row where it is, and nothing is deleted
/// until the player confirms. The window's close button quits the main menu at once.
#[test]
fn failed_loads_and_world_management_leave_the_list_and_the_saves_as_they_were() {
    let dir = TempDir::new("management");
    let (writes, wall) = (Writes::default(), Wall::default());
    let mut app = lifecycle_app(&dir.0, &writes, &wall);
    wall.set(1_000);
    let alpha = new_game(&mut app, "Alpha", Some(7));
    return_to_menu(&mut app);
    wall.set(2_000);
    // A blank seed: a random one, which the World keeps.
    let beta = new_game(&mut app, "Beta", None);
    return_to_menu(&mut app);
    assert_eq!(
        store(&app).load(&beta.id).expect("Beta loads").summary.seed,
        beta.seed
    );
    assert_eq!(listed_names(&app), ["Beta", "Alpha"]);
    let store = store(&app);

    // A damaged save fails to load, and stays as it is.
    let alpha_path = store.path_of(&alpha.id);
    let mut damaged = fs::read(&alpha_path).expect("Alpha's save");
    *damaged.last_mut().expect("a byte") ^= 0xff;
    fs::write(&alpha_path, &damaged).expect("damaged");
    act(&mut app, MenuAction::LoadGame(alpha.id));
    menu_idle(&mut app);
    let problem = menu(&app).problem.clone().expect("the load failed");
    assert_eq!(problem.job, MenuJob::Loading(alpha.id));
    assert!(problem.message.contains("damaged"), "{}", problem.message);
    assert_eq!(session(&app), Session::Closed);
    assert!(app.world().get_resource::<SimBridge>().is_none());
    assert_eq!(menu(&app).selected, Some(alpha.id));
    assert_eq!(fs::read(&alpha_path).expect("Alpha's save"), damaged);

    // A rename that fails to write, and one to a blank name, leave the name as it was.
    let beta_path = store.path_of(&beta.id);
    let beta_save = fs::read(&beta_path).expect("Beta's save");
    writes.fail(true);
    act(
        &mut app,
        MenuAction::Rename {
            id: beta.id,
            name: "Gamma".into(),
        },
    );
    menu_idle(&mut app);
    let problem = menu(&app).problem.clone().expect("the rename failed");
    assert_eq!(problem.job, MenuJob::Renaming(beta.id));
    assert_eq!(listed_names(&app), ["Beta", "Alpha"]);
    assert_eq!(menu(&app).selected, Some(beta.id));
    assert_eq!(fs::read(&beta_path).expect("Beta's save"), beta_save);
    writes.fail(false);
    act(
        &mut app,
        MenuAction::Rename {
            id: beta.id,
            name: "   ".into(),
        },
    );
    assert_eq!(
        menu(&app).problem.as_ref().map(|problem| &problem.job),
        Some(&MenuJob::Renaming(beta.id))
    );
    assert_eq!(fs::read(&beta_path).expect("Beta's save"), beta_save);

    // A rename that works keeps the row in its place, the World selected, and its progress.
    act(
        &mut app,
        MenuAction::Rename {
            id: beta.id,
            name: "  Gamma ".into(),
        },
    );
    menu_idle(&mut app);
    assert_eq!(menu(&app).problem, None);
    assert_eq!(listed_names(&app), ["Gamma", "Alpha"]);
    assert_eq!(menu(&app).selected, Some(beta.id));
    let renamed = store.load(&beta.id).expect("Gamma loads");
    assert_eq!(renamed.summary.name, "Gamma");
    assert_eq!(renamed.summary.last_played, Wall::at(2_000));
    assert_eq!(renamed.summary.seed, beta.seed);

    // Nothing is deleted until the player confirms.
    act(&mut app, MenuAction::AskToDelete(beta.id));
    assert_eq!(menu(&app).confirming_delete, Some(beta.id));
    act(&mut app, MenuAction::CancelDelete);
    assert_eq!(menu(&app).confirming_delete, None);
    menu_idle(&mut app);
    assert!(beta_path.exists());

    // A delete that fails keeps the list as it was: here, the save was removed behind its back.
    fs::remove_file(&beta_path).expect("removed");
    act(&mut app, MenuAction::AskToDelete(beta.id));
    act(&mut app, MenuAction::ConfirmDelete);
    menu_idle(&mut app);
    let problem = menu(&app).problem.clone().expect("the delete failed");
    assert_eq!(problem.job, MenuJob::Deleting(beta.id));
    assert_eq!(listed_names(&app), ["Gamma", "Alpha"]);
    assert_eq!(menu(&app).confirming_delete, None);

    // One that works takes the World out of the list.
    act(&mut app, MenuAction::AskToDelete(alpha.id));
    act(&mut app, MenuAction::ConfirmDelete);
    menu_idle(&mut app);
    assert_eq!(menu(&app).problem, None);
    assert_eq!(listed_names(&app), ["Gamma"]);
    assert_eq!(menu(&app).selected, None);
    assert!(!alpha_path.exists());
    act(&mut app, MenuAction::ListWorlds);
    menu_idle(&mut app);
    assert!(menu(&app).worlds.is_empty());

    // With no World open, the window's close button quits at once.
    close_window(&mut app);
    assert_eq!(app.should_exit(), Some(AppExit::Success));
}

/// Seam 3: leaving holds the World paused until its save commits. When the save fails, the
/// player can retry, cancel back to where they were (the pause menu, or play), or leave without
/// saving, which keeps the last save. Both ways of leaving: returning to the main menu, and the
/// window's close button.
#[test]
fn leaving_waits_for_its_save_and_a_failure_offers_retry_cancel_or_leaving_anyway() {
    let dir = TempDir::new("leaving");
    let (writes, wall) = (Writes::default(), Wall::default());
    let mut app = lifecycle_app(&dir.0, &writes, &wall);
    let world = new_game(&mut app, "Stubborn", Some(3));
    let path = store(&app).path_of(&world.id);
    let committed = fs::read(&path).expect("the first save");
    writes.fail(true);

    // From the pause menu, back to the main menu.
    pause(&mut app);
    act(&mut app, MenuAction::ReturnToMainMenu);
    assert_eq!(play(&app), Some(Play::Leaving));
    update_until(&mut app, "the save for leaving fails", |app| {
        departure(app).is_some_and(|departure| departure.failed.is_some())
    });
    assert_eq!(
        departure(&app).map(|departure| (departure.to, departure.back_to)),
        Some((Destination::MainMenu, Play::Paused))
    );
    assert_eq!(session(&app), Session::Open, "the World stays open");
    tap(&mut app, KeyCode::Escape);
    assert_eq!(play(&app), Some(Play::Leaving), "Esc doesn't resume it");

    let attempts = writes.attempts();
    act(&mut app, MenuAction::RetryLeaving);
    assert_eq!(departure(&app).and_then(|d| d.failed.clone()), None);
    update_until(&mut app, "the retry fails too", |app| {
        departure(app).is_some_and(|departure| departure.failed.is_some())
    });
    assert_eq!(writes.attempts(), attempts + 1);

    act(&mut app, MenuAction::CancelLeaving);
    update_until(&mut app, "back at the pause menu", |app| {
        play(app) == Some(Play::Paused)
    });
    assert_eq!(departure(&app), None);

    // From play, by the window's close button.
    tap(&mut app, KeyCode::Escape);
    assert_eq!(play(&app), Some(Play::Running));
    close_window(&mut app);
    update_until(&mut app, "the save for quitting fails", |app| {
        departure(app).is_some_and(|departure| departure.failed.is_some())
    });
    assert_eq!(
        departure(&app).map(|departure| (departure.to, departure.back_to)),
        Some((Destination::Desktop, Play::Running))
    );
    assert_eq!(app.should_exit(), None);
    act(&mut app, MenuAction::CancelLeaving);
    update_until(&mut app, "back in play", |app| {
        play(app) == Some(Play::Running) && app.world().resource::<InputPolicy>().gameplay
    });

    // Leaving without saving keeps the last save.
    close_window(&mut app);
    update_until(&mut app, "the save for quitting fails again", |app| {
        departure(app).is_some_and(|departure| departure.failed.is_some())
    });
    act(&mut app, MenuAction::LeaveWithoutSaving);
    assert_eq!(app.should_exit(), Some(AppExit::Success));
    assert_eq!(fs::read(&path).expect("the save"), committed);
}

/// Seam 3: the save for leaving waits behind one under way, and still holds the World as the
/// player left it, after an Edit the earlier save missed.
#[test]
fn the_save_for_leaving_waits_behind_one_under_way_and_holds_the_world_as_left() {
    let dir = TempDir::new("behind");
    let (writes, wall) = (Writes::default(), Wall::default());
    let mut app = lifecycle_app(&dir.0, &writes, &wall);
    let world = new_game(&mut app, "Patient", Some(5));

    writes.hold.store(true, Ordering::SeqCst);
    act(&mut app, MenuAction::Save);
    update_until(&mut app, "the save is held as it writes", |_| {
        writes.held.load(Ordering::SeqCst)
    });
    let granite = place_granite_above(&mut app);
    act(&mut app, MenuAction::ReturnToMainMenu);
    update_until(&mut app, "the World freezes", |app| {
        app.world().resource::<SimBridge>().frozen_at().is_some()
    });
    let frozen_at = app
        .world()
        .resource::<SimBridge>()
        .frozen_at()
        .expect("frozen");
    // Still waiting on the first save.
    for _ in 0..10 {
        app.update();
    }
    assert_eq!(session(&app), Session::Open);
    assert_eq!(saving(&app).in_progress(), Some(SaveReason::Manual));

    writes.hold.store(false, Ordering::SeqCst);
    update_until(&mut app, "the main menu shows", |app| {
        session(app) == Session::Closed
    });
    let left = store(&app).load(&world.id).expect("the save loads");
    let checkpoint = &left.save.capture.checkpoint;
    assert_eq!(checkpoint.tick_count, frozen_at);
    let stored = checkpoint
        .chunks
        .get(&ChunkPos::of(granite))
        .map(|chunk| &chunk.contents);
    let Some(ChunkContents::Cells(cells)) = stored else {
        panic!("the Edit's Chunk differs from the generated terrain, so its Cells are stored");
    };
    let granite_id = left
        .save
        .capture
        .elements
        .id_of("Granite")
        .expect("Granite");
    assert!(
        cells.iter().any(|cell| cell.element == granite_id),
        "the Granite is in the save"
    );
}
